using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();
        await _appHost.StartAsync();

        _chatClient = _appHost.Application.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert — basic sanity check
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Response should not be empty.");
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevance()
    {
        // Arrange
        var evaluator = new RelevanceTruthAndCompletenessEvaluator();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var chatHistory = messages.Concat(response.Messages).ToList();

        var result = await evaluator.EvaluateAsync(chatHistory, _chatClient);

        // Assert
        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Rating >= EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_EvaluateCoherence()
    {
        // Arrange
        var evaluator = new CoherenceEvaluator();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "List three benefits of cloud computing.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var chatHistory = messages.Concat(response.Messages).ToList();

        var result = await evaluator.EvaluateAsync(chatHistory, _chatClient);

        // Assert
        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Rating >= EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_EvaluateFluency()
    {
        // Arrange
        var evaluator = new FluencyEvaluator();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Describe how dependency injection works.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var chatHistory = messages.Concat(response.Messages).ToList();

        var result = await evaluator.EvaluateAsync(chatHistory, _chatClient);

        // Assert
        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Rating >= EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }
}

